// Frozen bounded natural partial-relation collector for #75/#76/#84.
// Public E/F_1009; the collector receives Q as a point and never its log.
// Source rows arise from a seeded aG+bQ stream and exact F+F, F+L, L+L
// membership. Every output row is replayed against original source IDs.
use std::collections::HashMap;
use std::time::Instant;
const P:i64=1009;const R:i64=1013;const SMALL:usize=8;const LARGE:usize=16;
const COLS:usize=SMALL+LARGE+2;const QCOL:usize=SMALL+LARGE;const RHS:usize=QCOL+1;
const TARGET:i64=701;const CAP:usize=512;const SEED:u64=0x7516_2026_1125;
#[derive(Clone,Copy,Debug,Eq,PartialEq,Hash)]enum Pt{O,A(i64,i64)}
fn m(x:i64,n:i64)->i64{x.rem_euclid(n)}
fn inv(x:i64,n:i64)->i64{let(mut a,mut b,mut u,mut v)=(m(x,n),n,1,0);while b!=0{let q=a/b;(a,b)=(b,a-q*b);(u,v)=(v,u-q*v)}assert_eq!(a,1);m(u,n)}
fn neg(q:Pt)->Pt{match q{Pt::O=>q,Pt::A(x,y)=>Pt::A(x,m(-y,P))}}
fn add(q:Pt,t:Pt)->Pt{match(q,t){(Pt::O,v)|(v,Pt::O)=>v,(Pt::A(x,y),Pt::A(u,v))=>{if x==u&&m(y+v,P)==0{return Pt::O}let s=if x==u{m((3*x*x+1)*inv(2*y,P),P)}else{m((v-y)*inv(u-x,P),P)};let xx=m(s*s-x-u,P);Pt::A(xx,m(s*(x-xx)-y,P))}}}
#[derive(Default,Clone,Copy)]struct Cost{group_adds:u64,mod_adds:u64,mod_muls:u64,mod_invs:u64,lookups:u64,rank_checks:u64}
fn ca(a:Pt,b:Pt,c:&mut Cost)->Pt{c.group_adds+=1;add(a,b)}
fn cm(mut k:i64,mut q:Pt,c:&mut Cost)->Pt{if k<0{k=-k;q=neg(q)}let mut out=Pt::O;while k>0{if k&1!=0{out=ca(out,q,c)}q=ca(q,q,c);k>>=1}out}
fn valid(q:Pt)->bool{match q{Pt::O=>true,Pt::A(x,y)=>m(y*y-x*x*x-x-14,P)==0}}
fn ma(a:i64,b:i64,c:&mut Cost)->i64{c.mod_adds+=1;m(a+b,R)}
fn mm(a:i64,b:i64,c:&mut Cost)->i64{c.mod_muls+=1;m(a*b,R)}
fn mi(a:i64,c:&mut Cost)->i64{c.mod_invs+=1;inv(a,R)}
#[derive(Clone,Copy,Debug)]enum Kind{Full,One,Two}
#[derive(Clone,Copy,Debug)]struct Decomp{kind:Kind,i:usize,j:usize}
#[derive(Clone)]struct Source{id:usize,a:i64,b:i64,r:Pt,row:[i64;COLS],kind:Kind}
#[derive(Clone)]struct Combined{row:[i64;COLS],w:Vec<i64>}
fn base()->(Vec<Pt>,u64,i64){let mut out=Vec::new();let mut tests=0;let mut xmax=0;for x in 0..P{for y in 0..P{tests+=1;let q=Pt::A(x,y);if valid(q){out.push(q);xmax=x;break}}if out.len()==SMALL+LARGE{break}}(out,tests,xmax+1)}
fn tables(base:&[Pt],c:&mut Cost)->(HashMap<Pt,Decomp>,HashMap<Pt,Decomp>,[usize;3]){
 let mut full=HashMap::new();let mut all=HashMap::new();let mut counts=[0;3];
 for i in 0..SMALL{for j in i..SMALL{let p=ca(base[i],base[j],c);let d=Decomp{kind:Kind::Full,i,j};full.entry(p).or_insert(d);all.entry(p).or_insert(d);counts[0]+=1}}
 for i in 0..SMALL{for j in SMALL..SMALL+LARGE{let p=ca(base[i],base[j],c);all.entry(p).or_insert(Decomp{kind:Kind::One,i,j});counts[1]+=1}}
 for i in SMALL..SMALL+LARGE{for j in i..SMALL+LARGE{let p=ca(base[i],base[j],c);all.entry(p).or_insert(Decomp{kind:Kind::Two,i,j});counts[2]+=1}}
 (full,all,counts)
}
fn next(state:&mut u64)->u64{*state^=*state<<13;*state^=*state>>7;*state^=*state<<17;*state}
fn stream(g:Pt,q:Pt)->(Vec<(i64,i64,Pt)>,Cost){let mut state=SEED;let mut out=Vec::new();let mut c=Cost::default();for _ in 0..CAP{let a=(next(&mut state)%R as u64)as i64;let b=1+(next(&mut state)%(R-1)as u64)as i64;let r=ca(cm(a,g,&mut c),cm(b,q,&mut c),&mut c);out.push((a,b,r))}(out,c)}
fn collect(s:&[(i64,i64,Pt)],table:&HashMap<Pt,Decomp>,base:&[Pt],q:Pt,g:Pt,c:&mut Cost,verify:&mut Cost)->Vec<Source>{let mut out=Vec::new();for (trial,&(a,b,r)) in s.iter().enumerate(){c.lookups+=1;if let Some(&d)=table.get(&r){let mut row=[0;COLS];row[d.i]+=1;row[d.j]+=1;row[QCOL]=m(-b,R);row[RHS]=a;assert_eq!(ca(base[d.i],base[d.j],verify),r);assert_eq!(ca(cm(a,g,verify),cm(b,q,verify),r));let id=out.len();out.push(Source{id,a,b,r,row,kind:d.kind});println!("source id={id} trial={trial} a={a} b={b} r={r:?} kind={:?} i={} j={}",d.kind,d.i,d.j)}}out}
fn combine(x:&mut Combined,p:&Combined,z:i64,c:&mut Cost){for j in 0..COLS{x.row[j]=ma(x.row[j],-mm(z,p.row[j],c),c)}for j in 0..x.w.len(){x.w[j]=ma(x.w[j],-mm(z,p.w[j],c),c)}}
fn filtered(src:&[Source],c:&mut Cost)->(Vec<Combined>,usize){let mut pivots:Vec<Option<Combined>>=vec![None;LARGE];let mut complete=Vec::new();let mut merges=0;for s in src{let mut w=vec![0;src.len()];w[s.id]=1;let mut x=Combined{row:s.row,w};let mut placed=false;for j in 0..LARGE{let col=SMALL+j;if x.row[col]==0{continue}if let Some(p)=&pivots[j]{let z=x.row[col];combine(&mut x,p,z,c);merges+=1}else{let z=mi(x.row[col],c);for v in &mut x.row{*v=mm(*v,z,c)}for v in &mut x.w{*v=mm(*v,z,c)}pivots[j]=Some(x);placed=true;break}}if !placed{assert!(x.row[SMALL..QCOL].iter().all(|&v|v==0));complete.push(x)}}(complete,merges)}
fn replay(x:&Combined,src:&[Source],base:&[Pt],q:Pt,g:Pt,c:&mut Cost){let mut row=[0;COLS];for (i,&z) in x.w.iter().enumerate(){if z!=0{for j in 0..COLS{row[j]=ma(row[j],mm(z,src[i].row[j],c),c)}}}assert_eq!(row,x.row);let mut point=Pt::O;for j in 0..SMALL+LARGE{if row[j]!=0{point=ca(point,cm(row[j],base[j],c),c)}}if row[QCOL]!=0{point=ca(point,cm(row[QCOL],q,c),c)}assert_eq!(point,cm(row[RHS],g,c))}
fn rank(rows:&[[i64;COLS]],with_target:bool,c:&mut Cost)->(usize,Option<i64>){c.rank_checks+=1;let cols=if with_target{SMALL+1}else{SMALL};let mut z:Vec<[i64;SMALL+2]>=rows.iter().map(|r|{let mut v=[0;SMALL+2];v[..SMALL].copy_from_slice(&r[..SMALL]);if with_target{v[SMALL]=r[QCOL]}v[SMALL+1]=r[RHS];v}).collect();let mut h=0;for col in 0..cols{if let Some(k)=(h..z.len()).find(|&i|z[i][col]!=0){z.swap(h,k);let p=mi(z[h][col],c);for j in col..SMALL+2{z[h][j]=mm(z[h][j],p,c)}let pivot=z[h];for i in 0..z.len(){if i!=h{let a=z[i][col];if a!=0{for j in col..SMALL+2{z[i][j]=ma(z[i][j],-mm(a,pivot[j],c),c)}}}}h+=1}}let mut answer=None;if with_target{for row in z{if row[..SMALL].iter().all(|&v|v==0)&&row[SMALL]!=0{answer=Some(mm(row[SMALL+1],mi(row[SMALL],c),c));break}}}(h,answer)}
fn analyse(label:&str,src:&[Source],base:&[Pt],q:Pt,g:Pt,setup:Cost,collect_cost:Cost,source_verify:Cost){let mut filter_cost=Cost::default();let mut replay_cost=Cost::default();let mut rank_cost=Cost::default();let start=Instant::now();let (complete,merges)=filtered(src,&mut filter_cost);for (i,x) in complete.iter().enumerate(){replay(x,src,base,q,g,&mut replay_cost);let support=x.w.iter().filter(|&&v|v!=0).count();println!("complete arm={label} id={i} sources={support} target_coeff={} rhs={}",x.row[QCOL],x.row[RHS])}let mut rows:Vec<[i64;COLS]>=complete.iter().map(|x|x.row).collect();let mut anchor=[0;COLS];anchor[0]=1;anchor[RHS]=1;rows.insert(0,anchor);let (rank_base,_)=rank(&rows,false,&mut rank_cost);let(rank_aug,answer)=rank(&rows,true,&mut rank_cost);if let Some(d)=answer{let mut check=Cost::default();assert_eq!(cm(d,g,&mut check),q);assert_eq!(d,TARGET)}let mut keep=Vec::new();for r in &rows{let old=rank(&keep,true,&mut rank_cost).0;let mut next=keep.clone();next.push(*r);if rank(&next,true,&mut rank_cost).0>old{keep.push(*r)}}let (keep_rank,keep_answer)=rank(&keep,true,&mut rank_cost);assert_eq!(keep_rank,rank_aug);assert_eq!(keep_answer,answer);let ms=start.elapsed().as_micros();println!("arm={label} trials={CAP} source_rows={} complete_rows={} independent_rows={} rank_base={rank_base} rank_aug={rank_aug} target_pinned={} recovered={} merges={merges} setup_group_adds={} candidate_group_adds={} source_verify_group_adds={} filter_mod_adds={} filter_mod_muls={} filter_mod_invs={} replay_group_adds={} replay_mod_adds={} replay_mod_muls={} rank_mod_adds={} rank_mod_muls={} rank_mod_invs={} relation_lookups={} filter_replay_rank_wall_us={ms}",src.len(),complete.len(),keep.len(),answer.is_some(),answer.unwrap_or(-1),setup.group_adds,collect_cost.group_adds,source_verify.group_adds,filter_cost.mod_adds,filter_cost.mod_muls,filter_cost.mod_invs,replay_cost.group_adds,replay_cost.mod_adds,replay_cost.mod_muls,rank_cost.mod_adds,rank_cost.mod_muls,rank_cost.mod_invs,collect_cost.lookups)}
fn main(){let g=Pt::A(0,425);assert!(valid(g));let mut target_setup=Cost::default();let q=cm(TARGET,g,&mut target_setup);assert_eq!(cm(R,g,&mut Cost::default()),Pt::O);let count=1+(0..P).flat_map(|x|(0..P).map(move|y|Pt::A(x,y))).filter(|&pt|valid(pt)).count();assert_eq!(count,R as usize);let(base,y_tests,x_scans)=base();assert_eq!(base[0],g);let mut setup=Cost::default();let(full,all,pair_counts)=tables(&base,&mut setup);let(stream,candidate_cost)=stream(g,q);let mut full_cost=Cost::default();let mut full_verify=Cost::default();let full_src=collect(&stream,&full,&base,q,g,&mut full_cost,&mut full_verify);let mut all_cost=Cost::default();let mut all_verify=Cost::default();let all_src=collect(&stream,&all,&base,q,g,&mut all_cost,&mut all_verify);let mut kinds=[0;3];for s in &all_src{match s.kind{Kind::Full=>kinds[0]+=1,Kind::One=>kinds[1]+=1,Kind::Two=>kinds[2]+=1}}assert_eq!(full_src.len(),kinds[0]);for(i,s)in full_src.iter().enumerate(){assert_eq!(s.row,all_src.iter().filter(|r|matches!(r.kind,Kind::Full)).nth(i).unwrap().row)}println!("input curve_p={P} order={R} group_count={count} seed={SEED} cap={CAP} target_point={q:?} target_generation_group_adds={} base_y_tests={y_tests} base_x_scans={x_scans} small={SMALL} large={LARGE} pair_work={pair_counts:?} full_keys={} all_keys={} all_kind_counts={kinds:?}",target_setup.group_adds,full.len(),all.len());let full_setup=Cost{group_adds:pair_counts[0] as u64,..Cost::default()};analyse("full_only",&full_src,&base,q,g,full_setup,candidate_cost,full_verify);analyse("partial_filter",&all_src,&base,q,g,setup,candidate_cost,all_verify);println!("claim_boundary=bounded_public_EFp_natural_collector source_rows_exact=true target_log_hidden_from_collector=true source_witness_replay=true full_setup_and_candidate_group_adds_reported=true field_arithmetic_inside_group_add_unpriced=true wall_noncomparative=true");}
